  ctx.restore();
}
var figCandSeg = null;

/* ---------- interaction ---------- */
function figHitTest(mx, my) {
  var best = null, bd = 9;
  if (figState.showRef) {
    for (var i = 0; i < FIG_LINES.length; i++) {
      var L = FIG_LINES[i];
      if (!L._p1) continue;
      var d = segDist(mx, my, L._p1[0], L._p1[1], L._p2[0], L._p2[1]);
      if (d < bd) { bd = d; best = { kind: 'ref', L: L }; }
    }
  }
  if (figCandSeg) {
    var dc = segDist(mx, my, figCandSeg[0][0], figCandSeg[0][1], figCandSeg[1][0], figCandSeg[1][1]);
    if (dc < bd) { bd = dc; best = { kind: 'cand' }; }
  }
  return best;
}

figCanvas.addEventListener('mousemove', function (ev) {
  var r = figCanvas.getBoundingClientRect();
  var hit = figHitTest(ev.clientX - r.left, ev.clientY - r.top);
  figCanvas.style.cursor = hit ? 'pointer' : 'default';
  if (hit && hit.kind === 'ref') {
    showTooltip('Line ' + hit.L.id + ':  ' + eqOf(hit.L.m, hit.L.b) +
      '   (slope ' + fmtNum(hit.L.m) + ', y-intercept ' + fmtNum(hit.L.b) + ') — click for rise/run', ev);
  } else if (hit && hit.kind === 'cand') {
    showTooltip('Candidate line: ' + eqOf(figState.m, figState.b) + ' — drag the sliders to move it', ev);
  } else hideTooltip();
});
figCanvas.addEventListener('mouseleave', function () { hideTooltip(); });

figCanvas.addEventListener('click', function (ev) {
  var r = figCanvas.getBoundingClientRect();
  var hit = figHitTest(ev.clientX - r.left, ev.clientY - r.top);
  if (hit && hit.kind === 'ref') {
    selectLine(hit.L.id);
    var L = hit.L;
    showPopup('Line ' + L.id + ':  ' + eqOf(L.m, L.b),
      'Follow the staircase: move ' + (Math.abs(L.m) < 1 ? 2 : 1) + ' unit(s) right and the line ' +
      (L.m >= 0 ? 'rises ' : 'falls ') + fmtNum(Math.abs(L.m * (Math.abs(L.m) < 1 ? 2 : 1))) +
      ', so the slope is m = ' + fmtNum(L.m) + '. It crosses the y-axis at ' + fmtNum(L.b) + ', so b = ' + fmtNum(L.b) +
      '. Those two numbers are the whole equation: ' + eqOf(L.m, L.b) + '. Set the sliders to these values and the dashed candidate lands exactly on top.');
  } else if (hit && hit.kind === 'cand') {
    showPopup('The candidate line',
      'This dashed line is y = mx + b with m and b taken straight from the sliders. Changing m pivots it about the point (0, b); changing b slides it up or down without altering its tilt. Matching a graph means finding the single (m, b) pair that makes this dashed line disappear into it.');
  } else {
    figState.selected = null;
    figChart.update('none');
  }
});

function selectLine(id) {
  figState.selected = (figState.selected === id) ? null : id;
  if (!figState.showRef) { figState.showRef = true; document.getElementById('showCandidateInput').checked = true; }
  figChart.update('none');
}

/* ---------- controls ---------- */
function syncReadout() {
  document.getElementById('eqReadout').textContent = eqOf(figState.m, figState.b);
  var matched = null;
  for (var q = 0; q < FIG_LINES.length; q++) {
    if (Math.abs(FIG_LINES[q].m - figState.m) < 0.13 && Math.abs(FIG_LINES[q].b - figState.b) < 0.26) matched = FIG_LINES[q];
  }
  var el = document.getElementById('matchReadout');
  if (matched) { el.textContent = '\u2714 matches line ' + matched.id; el.style.color = matched.color; }
  else { el.textContent = 'candidate line (dashed) — no match yet'; el.style.color = '#444'; }
}

function update_slopeSlider(v) { figState.m = v; syncReadout(); figChart.update('none'); }
function update_interceptSlider(v) { figState.b = v; syncReadout(); figChart.update('none'); }
function toggle_showCandidate(on) {
  figState.showRef = on;
  if (!on) figState.selected = null;
  figChart.update('none');
}

/* ---------- demo steps ---------- */
var STEPS = [
  { title: 'Four lines, four equations', narration: 'Four lines cross the same grid: orange I is steepest, light blue II is the shallowest, teal III rises from \u22123, and dark blue IV is the only one falling. Your job is to read each line\u2019s slope and intercept.', state: { showCandidate: true, slopeSlider: 1, interceptSlider: 0 } },
  { title: 'Rotate the candidate line', narration: 'Drag the slope slider and watch the dashed line pivot about the origin. Large positive m gives a steep climb like line I; small positive m gives a shallow climb like line II.', state: { slopeSlider: 3, interceptSlider: 0 } },
  { title: 'Negative slope flips the direction', narration: 'Push m below zero and the dashed line tips the other way \u2014 only line IV has this downhill behaviour, so its equation must have a negative slope.', state: { slopeSlider: -2, interceptSlider: 0 } },
  { title: 'Lift the line with b', narration: 'Now raise b to 3. The line keeps its downhill tilt but slides up until it crosses the y-axis at 3 \u2014 it lands exactly on line IV. Slope plus intercept pins a line uniquely.', state: { slopeSlider: -2, interceptSlider: 3 } },
  { title: 'Same intercept, different slope', narration: 'Keep b = 3 and set m = 0.5. The line still passes through (0, 3) but now leans gently upward onto line II \u2014 proof that b alone cannot identify a line.', state: { slopeSlider: 0.5, interceptSlider: 3 } },
  { title: 'Match line III', narration: 'Line III\u2019s rise-over-run staircase is shown: 1 right, 2 up, so m = 2; it cuts the y-axis at \u22123. With m = 2 and b = \u22123 the dashed candidate overlays it, confirming y = 2x \u2212 3.', state: { slopeSlider: 2, interceptSlider: -3 }, select: 'III' },
  { title: 'Test yourself', narration: 'Lines I\u2013IV are hidden: reproduce line I from memory \u2014 a steep positive slope with a small positive intercept. Tick \u201cReference lines\u201d to check your answer.', state: { showCandidate: false, slopeSlider: 3, interceptSlider: 0.5 } }
];

function setSlider(id, v) {
  var inp = document.getElementById(id + 'Input');
  if (!inp || v === undefined) return;
  inp.value = v;
  document.getElementById(id + 'Val').value = v;
  if (id === 'slopeSlider') figState.m = +v; else figState.b = +v;
}

function applyStep(i) {
  figState.step = i;
  var s = STEPS[i];
  if (s.state.showCandidate !== undefined) {
    var on = !!s.state.showCandidate;
    document.getElementById('showCandidateInput').checked = on;
    figState.showRef = on;
  }
  setSlider('slopeSlider', s.state.slopeSlider);
  setSlider('interceptSlider', s.state.interceptSlider);
  figState.selected = (s.select && figState.showRef) ? s.select : null;
  document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  document.getElementById('stepLabel').textContent = (i + 1) + ' / ' + STEPS.length;
  syncReadout();
  figChart.update('none');
}
function nextStep() { applyStep(Math.min(STEPS.length - 1, figState.step + 1)); }
function prevStep() { applyStep(Math.max(0, figState.step - 1)); }
function resetSteps() { applyStep(0); }

applyStep(0);
setTimeout(fitScales, 30);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
