// @FIGURE_CODE_BEGIN
var figContainer = document.getElementById('container');
var figCanvas = document.createElement('canvas');
figCanvas.style.cssText = 'width:100%;height:100%;display:block';
figContainer.appendChild(figCanvas);

var GX = [-6.8, 6.8];      // grid rectangle in world units
var GY = [-5.3, 5.3];

var FIG_LINES = [
  { id: 'I',   m: 3,    b: 1,    color: '#ee6c34' },
  { id: 'II',  m: 0.5,  b: 3,    color: '#3fa4dd' },
  { id: 'III', m: 2,    b: -3,   color: '#12988f' },
  { id: 'IV',  m: -2,   b: 3,    color: '#1f4e79' }
];
var CAND_COLOR = '#c62fa4';

var figState = { m: 1, b: 0, showRef: true, candVisible: false, selected: null, step: 0 };
var figCandSeg = null;

/* ---------- helpers ---------- */
function fmtNum(v) { return (Math.round(v * 100) / 100).toString().replace('-', '\u2212'); }

function eqOf(m, b) {
  var ms;
  if (m === 0) ms = '';
  else if (m === 1) ms = 'x';
  else if (m === -1) ms = '\u2212x';
  else ms = fmtNum(m) + 'x';
  var bs = '';
  if (b > 0) bs = (ms ? ' + ' : '') + fmtNum(b);
  else if (b < 0) bs = (ms ? ' \u2212 ' : '\u2212') + fmtNum(Math.abs(b));
  else if (!ms) bs = '0';
  return 'y = ' + ms + bs;
}

function clipLine(m, b) {
  var cand = [[GX[0], m * GX[0] + b], [GX[1], m * GX[1] + b]];
  if (Math.abs(m) > 1e-9) {
    cand.push([(GY[0] - b) / m, GY[0]]);
    cand.push([(GY[1] - b) / m, GY[1]]);
  }
  var eps = 1e-6, ok = [];
  for (var i = 0; i < cand.length; i++) {
    var p = cand[i];
    if (p[0] >= GX[0] - eps && p[0] <= GX[1] + eps && p[1] >= GY[0] - eps && p[1] <= GY[1] + eps) ok.push(p);
  }
  if (ok.length < 2) return null;
  ok.sort(function (a, c) { return a[0] - c[0]; });
  return [ok[0], ok[ok.length - 1]];
}

function segDist(px, py, x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1, L2 = dx * dx + dy * dy;
  var t = L2 ? ((px - x1) * dx + (py - y1) * dy) / L2 : 0;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
}

function matchedLine() {
  for (var q = 0; q < FIG_LINES.length; q++) {
    if (Math.abs(FIG_LINES[q].m - figState.m) < 0.13 && Math.abs(FIG_LINES[q].b - figState.b) < 0.26) return FIG_LINES[q];
  }
  return null;
}

/* ---------- chart ---------- */
function computeDomains(w, h) {
  var BX = 16.2, BY = 12.6, xr, yr;
  if (w / h >= BX / BY) { yr = BY; xr = BY * w / h; } else { xr = BX; yr = BX * h / w; }
  return { x: [-xr / 2, xr / 2], y: [-yr / 2, yr / 2] };
}

var figPlugin = {
  id: 'figLinesPlugin',
  afterDatasetsDraw: function (c) { figDraw(c); }
};

var figChart = new Chart(figCanvas.getContext('2d'), {
  type: 'scatter',
  data: { datasets: [{ data: [], showLine: false, pointRadius: 0 }] },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    layout: { padding: 4 },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { type: 'linear', min: -8.1, max: 8.1, grid: { display: false }, border: { display: false }, ticks: { display: false } },
      y: { type: 'linear', min: -6.3, max: 6.3, grid: { display: false }, border: { display: false }, ticks: { display: false } }
    }
  },
  plugins: [figPlugin]
});
window.__markRendered();

function fitScales() {
  var r = figCanvas.getBoundingClientRect();
  if (!r.width || !r.height) return;
  var d = computeDomains(Math.max(20, r.width - 8), Math.max(20, r.height - 8));
  var s = figChart.options.scales;
  s.x.min = d.x[0]; s.x.max = d.x[1];
  s.y.min = d.y[0]; s.y.max = d.y[1];
  figChart.update('none');
}
fitScales();
document.addEventListener('fig-resize', function () { fitScales(); });
window.addEventListener('resize', function () { setTimeout(fitScales, 0); });

/* ---------- drawing primitives ---------- */
function haloText(ctx, txt, x, y, color, align, baseline, fs, bold) {
  ctx.font = (bold ? 'bold ' : '') + fs + 'px sans-serif';
  ctx.textAlign = align; ctx.textBaseline = baseline;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(2.5, fs * 0.34);
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = color;
  ctx.fillText(txt, x, y);
}

function arrowHead(ctx, x, y, dx, dy, size, color) {
  var L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
  var px = -dy, py = dx;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - dx * size + px * size * 0.42, y - dy * size + py * size * 0.42);
  ctx.lineTo(x - dx * size - px * size * 0.42, y - dy * size - py * size * 0.42);
  ctx.closePath();
  ctx.fillStyle = color; ctx.fill();
}

/* fixed-corner equation card — never collides with the I–IV line labels */
function drawEqCard(ctx, area, x0, y0, txt, fs, color) {
  ctx.save();
  ctx.font = 'bold ' + (fs * 1.05).toFixed(1) + 'px sans-serif';
  var w = ctx.measureText(txt).width;
  var padx = fs * 0.55, pady = fs * 0.42;
  var bw = w + padx * 2, bh = fs * 1.05 + pady * 2;
  var bx = Math.min(x0, area.right - bw - 2);
  var by = Math.max(area.top + 1, y0);
  var r = Math.min(5, bh * 0.35);
  ctx.beginPath();
  ctx.moveTo(bx + r, by);
  ctx.lineTo(bx + bw - r, by); ctx.quadraticCurveTo(bx + bw, by, bx + bw, by + r);
  ctx.lineTo(bx + bw, by + bh - r); ctx.quadraticCurveTo(bx + bw, by + bh, bx + bw - r, by + bh);
  ctx.lineTo(bx + r, by + bh); ctx.quadraticCurveTo(bx, by + bh, bx, by + bh - r);
  ctx.lineTo(bx, by + r); ctx.quadraticCurveTo(bx, by, bx + r, by);
  ctx.closePath();
  ctx.fillStyle = 'rgba(255,255,255,0.93)'; ctx.fill();
  ctx.strokeStyle = color; ctx.lineWidth = 1; ctx.stroke();
  ctx.fillStyle = color; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
  ctx.fillText(txt, bx + padx, by + bh / 2);
  ctx.restore();
}

/* ---------- main draw ---------- */
function figDraw(c) {
  var ctx = c.ctx, xs = c.scales.x, ys = c.scales.y, area = c.chartArea;
  var X = function (v) { return xs.getPixelForValue(v); };
  var Y = function (v) { return ys.getPixelForValue(v); };
  var S = Math.min(area.right - area.left, area.bottom - area.top);
  var fs = Math.max(7, Math.min(13, S * 0.033));
  var lw = Math.max(1.1, Math.min(3, S * 0.0062));
  var ah = Math.max(4.5, Math.min(11, S * 0.022));

  ctx.save();

