/* ---------- interaction ---------- */
function figHitTest(mx, my) {
  var S = Math.min(figCanvas.clientWidth, figCanvas.clientHeight);
  var tol = Math.max(6, S * 0.022);
  var best = null, bd = tol;
  if (figState.showRef) {
    for (var i = 0; i < FIG_LINES.length; i++) {
      var L = FIG_LINES[i];
      if (!L._p1) continue;
      var d = segDist(mx, my, L._p1[0], L._p1[1], L._p2[0], L._p2[1]);
      if (d < bd) { bd = d; best = { kind: 'ref', L: L }; }
    }
  }
  if (figCandSeg) {
    var dc = segDist(mx, my, figCandSeg[0][0], figCandSeg[0][1], figCandSeg[1][0], figCandSeg[1][1]);
    if (dc < bd) { bd = dc; best = { kind: 'cand' }; }
  }
  return best;
}

figCanvas.addEventListener('mousemove', function (ev) {
  var r = figCanvas.getBoundingClientRect();
  var hit = figHitTest(ev.clientX - r.left, ev.clientY - r.top);
  figCanvas.style.cursor = hit ? 'pointer' : 'default';
  if (hit && hit.kind === 'ref') {
    showTooltip('Line ' + hit.L.id + ':  ' + eqOf(hit.L.m, hit.L.b) +
      '   (slope ' + fmtNum(hit.L.m) + ', y-intercept ' + fmtNum(hit.L.b) + ') — click for rise/run', ev);
  } else if (hit && hit.kind === 'cand') {
    showTooltip('Candidate line: ' + eqOf(figState.m, figState.b) + ' — drag the sliders to move it', ev);
  } else hideTooltip();
});
figCanvas.addEventListener('mouseleave', function () { hideTooltip(); });

figCanvas.addEventListener('click', function (ev) {
  var r = figCanvas.getBoundingClientRect();
  var hit = figHitTest(ev.clientX - r.left, ev.clientY - r.top);
  if (hit && hit.kind === 'ref') {
