    var L = hit.L, run = Math.abs(L.m) < 1 ? 2 : 1;
    showPopup('Line ' + L.id + ':  ' + eqOf(L.m, L.b),
      'Follow the staircase: move ' + run + ' unit(s) right and the line ' +
      (L.m >= 0 ? 'rises ' : 'falls ') + fmtNum(Math.abs(L.m * run)) +
      ', so the slope is m = ' + fmtNum(L.m) + '. It crosses the y-axis at ' + fmtNum(L.b) + ', so b = ' + fmtNum(L.b) +
      '. Those two numbers are the whole equation: ' + eqOf(L.m, L.b) + '. Set the sliders to these values and the dashed candidate lands exactly on top.');
  } else if (hit && hit.kind === 'cand') {
    showPopup('The candidate line',
      'This dashed line is y = mx + b with m and b taken straight from the sliders. Changing m pivots it about the point (0, b); changing b slides it up or down without altering its tilt. Matching a graph means finding the single (m, b) pair that makes this dashed line disappear into it.');
  } else {
    figState.selected = null;
    figChart.update('none');
  }
