/* ---------- drawing primitives ---------- */
function haloText(ctx, txt, x, y, color, align, baseline, fs, bold) {
  ctx.font = (bold ? 'bold ' : '') + fs + 'px sans-serif';
  ctx.textAlign = align; ctx.textBaseline = baseline;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(2.5, fs * 0.34);
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = color;
  ctx.fillText(txt, x, y);
}

function arrowHead(ctx, x, y, dx, dy, size, color) {
  var L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
  var px = -dy, py = dx;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - dx * size + px * size * 0.42, y - dy * size + py * size * 0.42);
  ctx.lineTo(x - dx * size - px * size * 0.42, y - dy * size - py * size * 0.42);
  ctx.closePath();
  ctx.fillStyle = color; ctx.fill();
}

/* fixed-corner equation card — never collides with the I–IV line labels */
function drawEqCard(ctx, area, x0, y0, txt, fs, color) {
  ctx.save();
  ctx.font = 'bold ' + (fs * 1.05).toFixed(1) + 'px sans-serif';
  var w = ctx.measureText(txt).width;
  var padx = fs * 0.55, pady = fs * 0.42;
  var bw = w + padx * 2, bh = fs * 1.05 + pady * 2;
  var bx = Math.min(x0, area.right - bw - 2);
  var by = Math.max(area.top + 1, y0);
  var r = Math.min(5, bh * 0.35);
  ctx.beginPath();
  ctx.moveTo(bx + r, by);
  ctx.lineTo(bx + bw - r, by); ctx.quadraticCurveTo(bx + bw, by, bx + bw, by + r);
  ctx.lineTo(bx + bw, by + bh - r); ctx.quadraticCurveTo(bx + bw, by + bh, bx + bw - r, by + bh);
  ctx.lineTo(bx + r, by + bh); ctx.quadraticCurveTo(bx, by + bh, bx, by + bh - r);
  ctx.lineTo(bx, by + r); ctx.quadraticCurveTo(bx, by, bx + r, by);
  ctx.closePath();
  ctx.fillStyle = 'rgba(255,255,255,0.93)'; ctx.fill();
  ctx.strokeStyle = color; ctx.lineWidth = 1; ctx.stroke();
  ctx.fillStyle = color; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
  ctx.fillText(txt, bx + padx, by + bh / 2);
  ctx.restore();
}

/* ---------- main draw ---------- */
function figDraw(c) {
