  var Y = function (v) { return ys.getPixelForValue(v); };
  var S = Math.min(area.right - area.left, area.bottom - area.top);
  var fs = Math.max(7, Math.min(13, S * 0.033));
  var lw = Math.max(1.1, Math.min(3, S * 0.0062));
  var ah = Math.max(4.5, Math.min(11, S * 0.022));

  ctx.save();

  /* grid */
  ctx.strokeStyle = '#d8d8d8'; ctx.lineWidth = 1;
  var i;
  for (i = Math.ceil(GX[0]); i <= Math.floor(GX[1]); i++) {
    ctx.beginPath(); ctx.moveTo(X(i), Y(GY[0])); ctx.lineTo(X(i), Y(GY[1])); ctx.stroke();
  }
  for (i = Math.ceil(GY[0]); i <= Math.floor(GY[1]); i++) {
